style.css:
@-moz-document domain("youtube.com") {
:root {
    --sage: #b6cf78;
    --sage-light: #edf4dc;
    --sage-pale: #f8fbed;
    --sage-dark: #60733d;
    --sage-deep: #344022;
    --cream: #fffef9;
    --dot: rgba(126, 157, 73, 0.22);
    --shadow: 0 8px 25px rgba(63, 83, 49, 0.14);
  }

  html,
  body,
  ytd-app {
    background-color: var(--sage-light) !important;
    background-image: radial-gradient(var(--dot) 1.4px, transparent 1.4px);
    background-size: 18px 18px;
    color: var(--sage-deep) !important;
  }

  #masthead-container,
  ytd-masthead,
  #masthead {
    background: rgba(248, 251, 237, 0.92) !important;
    backdrop-filter: blur(16px);
    border-bottom: 1px solid rgba(96, 115, 61, 0.15) !important;
  }

  #logo-icon,
  .yt-icon,
  #guide-icon,
  #notification-icon {
    color: var(--sage-dark) !important;
  }

  #search-form,
  #search {
    border-radius: 999px !important;
    overflow: hidden;
  }

  #search-input #search {
    background: var(--cream) !important;
    border: 1px solid rgba(96, 115, 61, 0.25) !important;
    box-shadow: none !important;
  }

  #search-icon-legacy,
  #search-icon-legacy.ytd-searchbox {
    background: var(--sage) !important;
    border: 0 !important;
    color: white !important;
  }

  input,
  #search-input input {
    color: var(--sage-deep) !important;
  }

  #guide-content,
  ytd-mini-guide-renderer {
    background: rgba(248, 251, 237, 0.88) !important;
  }

  ytd-guide-entry-renderer,
  ytd-mini-guide-entry-renderer {
    border-radius: 14px !important;
    margin: 3px 8px !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover,
  ytd-guide-entry-renderer[active] {
    background: var(--sage) !important;
    color: white !important;
  }

  yt-chip-cloud-chip-renderer,
  yt-chip-cloud-chip-renderer[modern] {
    background: var(--cream) !important;
    border: 1px solid rgba(96, 115, 61, 0.18) !important;
    border-radius: 999px !important;
    color: var(--sage-dark) !important;
  }

  yt-chip-cloud-chip-renderer:hover,
  yt-chip-cloud-chip-renderer[aria-selected="true"] {
    background: var(--sage-dark) !important;
    color: white !important;
  }

  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-grid-video-renderer,
  ytd-compact-video-renderer {
    background: rgba(255, 254, 249, 0.76) !important;
    border-radius: 18px !important;
  }

  ytd-rich-grid-media,
  ytd-video-renderer,
  ytd-compact-video-renderer {
    padding: 8px !important;
    border-radius: 18px !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease !important;
  }

  ytd-rich-grid-media:hover,
  ytd-video-renderer:hover,
  ytd-compact-video-renderer:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow) !important;
  }

  ytd-thumbnail,
  ytd-thumbnail a,
  ytd-thumbnail img,
  ytd-playlist-thumbnail {
    border-radius: 14px !important;
    overflow: hidden !important;
  }

  ytd-thumbnail img {
    filter: saturate(0.82) sepia(0.08) hue-rotate(20deg) !important;
  }

  #video-title,
  #video-title-link,
  yt-formatted-string,
  #channel-name,
  #byline-container {
    color: var(--sage-deep) !important;
  }

  #metadata-line,
  #metadata-line span,
  #description-text,
  #subtitle {
    color: #728168 !important;
  }

  button,
  yt-button-shape button,
  .yt-spec-button-shape-next {
    border-radius: 999px !important;
  }

  yt-button-shape button:hover,
  .yt-spec-button-shape-next:hover {
    background: var(--sage) !important;
    color: white !important;
  }

  ytd-reel-shelf-renderer,
  ytd-rich-shelf-renderer {
    background: rgba(255, 254, 249, 0.58) !important;
    border-radius: 24px !important;
    padding: 18px !important;
  }

  #below,
  ytd-watch-metadata,
  ytd-comments {
    background: rgba(255, 254, 249, 0.72) !important;
    border-radius: 22px !important;
    padding: 16px !important;
  }

  .html5-video-player {
    border-radius: 20px !important;
    overflow: hidden !important;
    box-shadow: var(--shadow) !important;
  }

  ytd-comment-thread-renderer,
  ytd-comment-renderer {
    background: rgba(255, 254, 249, 0.65) !important;
    border-radius: 16px !important;
    padding: 10px !important;
  }

  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: var(--sage-light);
  }

  ::-webkit-scrollbar-thumb {
    background: var(--sage);
    border-radius: 999px;
    border: 2px solid var(--sage-light);
  }

  #progress,
  .ytp-play-progress,
  .ytp-scrubber-button {
    background: var(--sage-dark) !important;
  }

  .ytp-volume-slider-handle,
  .ytp-volume-slider-track {
    background: var(--sage) !important;
  }
}
